"""Download every order listing page and the customer record of each customer seen.

Usage: python3 -I fetch.py <empty_output_dir>

Each successful response is written to the output directory as JSON. Failed requests
are retried, never skipped: a 401 or 403 gets a new token, a 429 waits for the time the
service asks for, anything else waits with exponential backoff. A 404 from
/customers/{id} is kept as the answer it is: that customer id is unknown.
"""
import json
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
MAX_ATTEMPTS = 60
ORDER_KEYS = ("page", "total_pages", "items", "next")
CUSTOMER_KEYS = ("id", "name", "region", "tier", "discount_pct")

out_dir = sys.argv[1]
log_file = open(os.path.join(out_dir, "fetch.log"), "w")
stats = {"requests": 0, "retries": 0, "token_refreshes": 0, "statuses": {}}


def log(msg):
    line = datetime.now(timezone.utc).strftime("%H:%M:%S") + " " + msg
    print(line, file=sys.stderr, flush=True)
    print(line, file=log_file, flush=True)


def send(method, path, token=None):
    """One request. Returns (status, body, headers); status is None if no HTTP answer came back."""
    headers = {"Authorization": "Bearer " + token} if token else {}
    data = b"" if method == "POST" else None
    req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
    stats["requests"] += 1
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            status, body, hdrs = resp.status, resp.read().decode("utf-8", "replace"), resp.headers
    except urllib.error.HTTPError as err:
        status, body, hdrs = err.code, err.read().decode("utf-8", "replace"), err.headers
    except Exception as err:  # refused, reset or timed out: no answer at all
        status, body, hdrs = None, repr(err), None
    stats["statuses"][str(status)] = stats["statuses"].get(str(status), 0) + 1
    return status, body, hdrs


def pause(status, body, hdrs, what, attempt):
    """Sleep before retrying: for a 429, as long as the service says; otherwise backoff."""
    wait = None
    if status == 429:
        raw = hdrs.get("Retry-After") if hdrs is not None else None
        if raw is None:
            try:
                raw = json.loads(body).get("retry_after")
            except (ValueError, AttributeError):
                raw = None
        try:
            wait = float(raw)
        except (TypeError, ValueError):
            wait = None
    if wait is None:
        wait = min(0.5 * 2 ** attempt, 30)
    stats["retries"] += 1
    log(f"{what}: status {status}, body {body[:200]!r}; waiting {wait:.1f}s")
    time.sleep(wait)


def get_token():
    for attempt in range(1, MAX_ATTEMPTS + 1):
        status, body, hdrs = send("POST", "/token")
        if status == 200:
            try:
                return json.loads(body)["token"]
            except (ValueError, KeyError, TypeError):
                pass
        pause(status, body, hdrs, "POST /token", attempt)
    raise SystemExit("could not obtain a token")


def call_api(path, state, keys):
    """GET an authenticated path until it returns JSON with the expected keys.
    Returns (200, data), or (404, None) for an unknown customer id."""
    for attempt in range(1, MAX_ATTEMPTS + 1):
        if state["token"] is None:
            state["token"] = get_token()
        status, body, hdrs = send("GET", path, state["token"])
        if status == 200:
            try:
                data = json.loads(body)
            except ValueError:
                data = None
            if isinstance(data, dict) and all(k in data for k in keys):
                return 200, data
        elif status == 404:
            return 404, None
        elif status in (401, 403):
            log(f"GET {path}: {status} {body.strip()[:120]!r}; fetching a new token")
            state["token"] = None
            stats["token_refreshes"] += 1
            continue
        pause(status, body, hdrs, f"GET {path}", attempt)
    raise SystemExit(f"gave up on GET {path} after {MAX_ATTEMPTS} attempts")


state = {"token": None}

# Listing: start at page 1 and follow "next" until it is null.
pages = []
path = "/orders?page=1"
while path is not None:
    _, data = call_api(path, state, ORDER_KEYS)
    pages.append(data)
    path = None
    if data["next"]:
        parts = urllib.parse.urlsplit(data["next"])
        path = parts.path + ("?" + parts.query if parts.query else "")
    if len(pages) > 1000:
        raise SystemExit("'next' never ended")

total = pages[0]["total_pages"]
if len(pages) != total:
    raise SystemExit(f"'next' gave {len(pages)} pages, total_pages says {total}")
for n, data in enumerate(pages, 1):
    if data["page"] != n:
        raise SystemExit(f"page {n} came back as page {data['page']}")
    if data["total_pages"] != total:
        log(f"page {n}: total_pages is {data['total_pages']}, page 1 said {total}")
    with open(os.path.join(out_dir, f"page-{n:03d}.json"), "w") as f:
        json.dump(data, f)
listings = sum(len(d["items"]) for d in pages)
log(f"listing: {total} pages, {listings} listings")

# Customers: one lookup per distinct id seen in the listings.
customer_ids = sorted({item["customer_id"] for d in pages for item in d["items"]})
customers = {}
for cid in customer_ids:
    status, data = call_api(f"/customers/{cid}", state, CUSTOMER_KEYS)
    customers[cid] = data if status == 200 else {"id": cid, "status": status}
with open(os.path.join(out_dir, "customers.json"), "w") as f:
    json.dump(customers, f)
unknown = [cid for cid, c in customers.items() if "status" in c]
log(f"customers: {len(customer_ids)} distinct ids, {len(unknown)} unknown: {unknown}")
log(f"stats: {stats}")

